<?php
declare(strict_types=1);

namespace AM2050\Services;

use AM2050\Core\Database;
use AM2050\Support\AuditLogger;
use AM2050\Support\Ulids;
use PDO;
use PDOException;
use RuntimeException;

final class DashboardOperationsService
{
    private const EXECUTIVE_ROLES=['super_admin','program_admin'];
    public function __construct(private readonly Database $db,private readonly AuditLogger $audit,private readonly InsightService $insights){}
    private function executive(array $auth):void{if(!in_array($auth['role']??'',self::EXECUTIVE_ROLES,true))throw new RuntimeException('Only programme administrators can manage owners, SLA targets, or executive packs.');}
    public function slaTargets(array $auth):array{$this->executive($auth);return $this->targets();}
    public function updateSlaTargets(array $auth,array $input):array{$this->executive($auth);$allowed=['enrollment_followup','attendance_followup','cnr','compliance','incentive'];$targets=[];foreach($allowed as$key){$value=$input[$key]??null;if(!is_numeric($value)||(int)$value<1||(int)$value>365)throw new RuntimeException('Each SLA target must be between 1 and 365 days.');$targets[$key]=(int)$value;}$pdo=$this->db->pdo();$before=$this->targets();$pdo->prepare('INSERT INTO program_rules(id,rule_key,rule_value,updated_by) VALUES(:id,"dashboardSlaTargets",:value,:user) ON DUPLICATE KEY UPDATE rule_value=VALUES(rule_value),updated_by=VALUES(updated_by)')->execute(['id'=>Ulids::make(),'value'=>json_encode($targets,JSON_THROW_ON_ERROR),'user'=>$auth['id']]);$this->audit->record($auth['id'],'UPDATE','dashboard_sla_targets','dashboard-sla-targets',$before,$targets);return $targets;}
    public function owners(array $auth,string $priorityKey):array{$this->assertManageSource($auth,$priorityKey);$source=$this->prioritySource($priorityKey);$pdo=$this->db->pdo();$stmt=$pdo->prepare('SELECT u.id,u.name,u.role,u.assigned_scope_type,u.assigned_scope_id FROM users u LEFT JOIN wards w ON w.id=:ward LEFT JOIN lgas l ON l.id=w.lga_id WHERE u.is_active=1 AND u.role IN ("super_admin","program_admin","lga_supervisor","ward_supervisor","mobilizer","headmaster","teacher") AND (u.role IN ("super_admin","program_admin") OR (u.assigned_scope_type="ward" AND u.assigned_scope_id=w.id) OR (u.assigned_scope_type="lga" AND u.assigned_scope_id=l.id) OR (u.assigned_scope_type="state" AND u.assigned_scope_id=l.state_id) OR ((u.assigned_scope_type="school" OR u.assigned_scope_type="class") AND EXISTS(SELECT 1 FROM enrollments e INNER JOIN school_classes sc ON sc.id=e.class_id WHERE e.child_id=:child AND e.enrollment_status="active" AND ((u.assigned_scope_type="school" AND u.assigned_scope_id=e.school_id) OR (u.assigned_scope_type="class" AND u.assigned_scope_id=sc.id)))) ) ORDER BY FIELD(u.role,"super_admin","program_admin","lga_supervisor","ward_supervisor","headmaster","teacher","mobilizer"),u.name');$stmt->execute(['ward'=>$source['ward_id'],'child'=>$source['child_id']]);return $stmt->fetchAll();}
    public function assign(array $auth,string $priorityKey,?string $ownerId):array{$this->assertManageSource($auth,$priorityKey);$source=$this->prioritySource($priorityKey);$pdo=$this->db->pdo();if($ownerId!==null&&$ownerId!==''){$eligible=array_column($this->owners($auth,$priorityKey),'id');if(!in_array($ownerId,$eligible,true))throw new RuntimeException('The selected staff member is not eligible to own this priority in the current scope.');}else $ownerId=null;$before=$this->assignment($priorityKey);$assignmentId=$before['id']??Ulids::make();$pdo->prepare('INSERT INTO dashboard_priority_assignments(id,priority_key,priority_type,source_entity_type,source_entity_id,owner_user_id,assigned_by) VALUES(:id,:key,:type,"child",:child,:owner,:by) ON DUPLICATE KEY UPDATE owner_user_id=VALUES(owner_user_id),assigned_by=VALUES(assigned_by),assigned_at=CURRENT_TIMESTAMP')->execute(['id'=>$assignmentId,'key'=>$priorityKey,'type'=>$source['type'],'child'=>$source['child_id'],'owner'=>$ownerId,'by'=>$auth['id']]);$pdo->prepare('INSERT INTO dashboard_priority_assignment_history(id,assignment_id,previous_owner_user_id,new_owner_user_id,changed_by) VALUES(:id,:assignment,:before,:after,:by)')->execute(['id'=>Ulids::make(),'assignment'=>$assignmentId,'before'=>$before['owner_user_id']??null,'after'=>$ownerId,'by'=>$auth['id']]);$after=$this->assignment($priorityKey);$this->audit->record($auth['id'],'ASSIGN','dashboard_priority',$source['child_id'],['priority_key'=>$priorityKey,'assignment'=>$before],['priority_key'=>$priorityKey,'assignment'=>$after]);return $after;}
    public function schedules(array $auth):array{$this->executive($auth);return $this->db->pdo()->query('SELECT s.*,u.name AS owner_name,c.name AS created_by_name FROM executive_dashboard_schedules s INNER JOIN users u ON u.id=s.owner_user_id INNER JOIN users c ON c.id=s.created_by ORDER BY s.is_active DESC,s.next_due_month')->fetchAll();}
    public function executiveOwners(array $auth):array{$this->executive($auth);return $this->db->pdo()->query('SELECT id,name,role FROM users WHERE is_active=1 AND role IN ("super_admin","program_admin") ORDER BY FIELD(role,"super_admin","program_admin"),name')->fetchAll();}
    public function createSchedule(array $auth,array $input):array{$this->executive($auth);$name=trim((string)($input['scheduleName']??''));$owner=(string)($input['ownerUserId']??'');$due=(string)($input['nextDueMonth']??'');if($name===''||!preg_match('/^\d{4}-\d{2}-01$/',$due))throw new RuntimeException('Provide a schedule name and a first-of-month next due date.');$this->assertExecutiveOwner($owner);$id=Ulids::make();$this->db->pdo()->prepare('INSERT INTO executive_dashboard_schedules(id,schedule_name,owner_user_id,next_due_month,created_by) VALUES(:id,:name,:owner,:due,:by)')->execute(['id'=>$id,'name'=>$name,'owner'=>$owner,'due'=>$due,'by'=>$auth['id']]);$record=$this->schedule($id);$this->audit->record($auth['id'],'CREATE','executive_dashboard_schedule',$id,null,$record);return $record;}
    public function updateSchedule(array $auth,string $id,array $input):array{$this->executive($auth);$before=$this->schedule($id);$sets=[];$params=['id'=>$id];if(array_key_exists('isActive',$input)){$sets[]='is_active=:active';$params['active']=$input['isActive']?1:0;}if(isset($input['ownerUserId'])){$this->assertExecutiveOwner((string)$input['ownerUserId']);$sets[]='owner_user_id=:owner';$params['owner']=$input['ownerUserId'];}if(isset($input['nextDueMonth'])){if(!preg_match('/^\d{4}-\d{2}-01$/',(string)$input['nextDueMonth']))throw new RuntimeException('Next due month must be the first day of a month.');$sets[]='next_due_month=:due';$params['due']=$input['nextDueMonth'];}if($sets===[])throw new RuntimeException('No schedule update was supplied.');$this->db->pdo()->prepare('UPDATE executive_dashboard_schedules SET '.implode(',',$sets).' WHERE id=:id')->execute($params);$after=$this->schedule($id);$this->audit->record($auth['id'],'UPDATE','executive_dashboard_schedule',$id,$before,$after);return $after;}
    public function packs(array $auth):array{$this->executive($auth);return $this->db->pdo()->query('SELECT p.id,p.period_month,p.scope_label,p.generated_at,s.schedule_name,u.name AS generated_by_name FROM executive_dashboard_packs p LEFT JOIN executive_dashboard_schedules s ON s.id=p.schedule_id INNER JOIN users u ON u.id=p.generated_by ORDER BY p.period_month DESC,p.generated_at DESC')->fetchAll();}
    public function generatePack(array $auth,array $input):array{$this->executive($auth);$scheduleId=isset($input['scheduleId'])&&$input['scheduleId']!==''?(string)$input['scheduleId']:null;$month=(string)($input['periodMonth']??gmdate('Y-m-01'));if(!preg_match('/^\d{4}-\d{2}-01$/',$month))throw new RuntimeException('Period month must be the first day of a month.');$schedule=$scheduleId?$this->schedule($scheduleId):null;if($scheduleId!==null&&($existing=$this->scheduleMonthPack($scheduleId,$month))!==null){$existing['was_reused']=true;return $existing;}$decision=$this->insights->decisionDashboard($auth);$scope='Programme-wide authorised scope';$id=Ulids::make();try{$this->db->pdo()->prepare('INSERT INTO executive_dashboard_packs(id,schedule_id,period_month,scope_label,metrics_snapshot,priorities_snapshot,trend_snapshot,generated_by) VALUES(:id,:schedule,:month,:scope,:metrics,:priorities,:trend,:by)')->execute(['id'=>$id,'schedule'=>$scheduleId,'month'=>$month,'scope'=>$scope,'metrics'=>json_encode($decision['metrics'],JSON_THROW_ON_ERROR),'priorities'=>json_encode($decision['priorityQueue'],JSON_THROW_ON_ERROR),'trend'=>json_encode($decision['trend'],JSON_THROW_ON_ERROR),'by'=>$auth['id']]);}catch(PDOException $error){if($error->getCode()==='23000'&&$scheduleId!==null&&($existing=$this->scheduleMonthPack($scheduleId,$month))!==null){$existing['was_reused']=true;return $existing;}throw $error;}if($schedule){$next=(new \DateTimeImmutable($month))->modify('first day of next month')->format('Y-m-d');$this->db->pdo()->prepare('UPDATE executive_dashboard_schedules SET last_generated_month=:month,next_due_month=:next WHERE id=:id')->execute(['month'=>$month,'next'=>$next,'id'=>$scheduleId]);}$pack=$this->pack($id);$pack['was_reused']=false;$this->audit->record($auth['id'],'GENERATE','executive_dashboard_pack',$id,null,['periodMonth'=>$month,'scheduleId'=>$scheduleId]);return $pack;}
    public function outputPack(array $auth,string $id):never{$this->executive($auth);$pack=$this->pack($id);$metrics=json_decode((string)$pack['metrics_snapshot'],true)?:[];$priorities=json_decode((string)$pack['priorities_snapshot'],true)?:[];$trend=json_decode((string)$pack['trend_snapshot'],true)?:[];$metricRows='';foreach($metrics as$m)$metricRows.='<tr><td>'.htmlspecialchars($m['label']).'</td><td>'.htmlspecialchars(($m['format']==='percent'?$m['value'].'%':(string)$m['value'])).'</td><td>'.htmlspecialchars($m['denominator']===null?'Current count':$m['numerator'].' of '.$m['denominator']).'</td><td>'.htmlspecialchars($m['dateRange']).'</td><td>'.htmlspecialchars($m['state']).'</td></tr>';$priorityRows='';foreach($priorities as$p)$priorityRows.='<tr><td>'.htmlspecialchars(strtoupper($p['severity'])).'</td><td>'.htmlspecialchars($p['summary']).'</td><td>'.htmlspecialchars($p['owner']).'</td><td>'.htmlspecialchars($p['nextAction']).'</td><td>'.htmlspecialchars($p['sla']).'</td></tr>';$points=$trend['series']??[];$trendText=isset($trend['recentAverage'])&&$trend['recentAverage']!==null?$trend['recentAverage'].'% recent attendance average; '.($trend['change']>=0?'+':'').$trend['change'].' points compared with previous period.':'No comparable attendance period was recorded.';$html='<!doctype html><html><head><style>body{font-family:DejaVu Sans,sans-serif;color:#123148;font-size:10px}h1{font-size:25px;margin:0}h2{font-size:15px;margin:24px 0 8px;color:#123148}.meta{color:#57707f;margin:5px 0 18px}.band{padding:11px;background:#123148;color:white;margin-bottom:18px}.rule{border-left:4px solid #c88b25;padding-left:10px}.metric{display:inline-block;width:23%;margin-right:1%;vertical-align:top;border:1px solid #cfd9d2;padding:8px;box-sizing:border-box}.metric strong{font-size:19px;display:block;margin:5px 0}table{width:100%;border-collapse:collapse}th{background:#edf2ee;text-align:left}th,td{border:1px solid #cfd9d2;padding:6px;vertical-align:top}.foot{margin-top:22px;color:#57707f;font-size:8px}</style></head><body><div class="band">AM2050 · AREWA MISSION 2050<br><strong>Monthly Executive Dashboard Pack</strong></div><h1>'.$this->esc(date('F Y',strtotime((string)$pack['period_month']))).'</h1><p class="meta">Generated '.htmlspecialchars((string)$pack['generated_at']).' · '.$this->esc((string)$pack['scope_label']).' · Prepared by '.htmlspecialchars((string)$pack['generated_by_name']).'</p><div class="rule">This pack is a fixed snapshot of the dashboard evidence available at generation. Counts, stated denominators, date ranges, methodology, and data states govern interpretation.</div><h2>Programme metric summary</h2><table><thead><tr><th>Metric</th><th>Value</th><th>Denominator</th><th>Date range</th><th>Data state</th></tr></thead><tbody>'.$metricRows.'</tbody></table><h2>Attendance change</h2><p>'.htmlspecialchars($trendText).'</p><p class="meta">'.htmlspecialchars((string)($trend['methodology']??'')).'</p><h2>Priority action queue</h2><table><thead><tr><th>Severity</th><th>Priority record</th><th>Owner</th><th>Next action</th><th>SLA</th></tr></thead><tbody>'.($priorityRows?:'<tr><td colspan="5">No open priority items in this snapshot.</td></tr>').'</tbody></table><p class="foot">AM2050 executive reporting · Authorised use only · Individual records remain available only through scoped AM2050 workflows.</p></body></html>';header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="am2050-executive-dashboard-'.date('Y-m',strtotime((string)$pack['period_month'])).'.pdf"');$pdf=new \Dompdf\Dompdf();$pdf->loadHtml($html);$pdf->setPaper('A4','portrait');$pdf->render();echo$pdf->output();exit;}
    private function targets():array{$raw=$this->db->pdo()->prepare('SELECT rule_value FROM program_rules WHERE rule_key="dashboardSlaTargets"');$raw->execute();$decoded=json_decode((string)$raw->fetchColumn(),true);return is_array($decoded)?$decoded:['enrollment_followup'=>14,'attendance_followup'=>7,'cnr'=>7,'compliance'=>14,'incentive'=>14];}
    private function assignment(string $key):?array{$s=$this->db->pdo()->prepare('SELECT a.*,u.name AS owner_name,u.role AS owner_role FROM dashboard_priority_assignments a LEFT JOIN users u ON u.id=a.owner_user_id WHERE a.priority_key=:key');$s->execute(['key'=>$key]);return$s->fetch()?:null;}
    private function prioritySource(string $key):array{if(!preg_match('/^(enrollment|attendance)-([0-9A-HJKMNP-TV-Z]{26})$/',$key,$m))throw new RuntimeException('Unsupported dashboard priority.');$s=$this->db->pdo()->prepare('SELECT c.id AS child_id,COALESCE(h.ward_id,c.ward_id) AS ward_id FROM children c LEFT JOIN households h ON h.id=c.household_id WHERE c.id=:id');$s->execute(['id'=>$m[2]]);$row=$s->fetch();if(!$row)throw new RuntimeException('Priority source is no longer available.');return['type'=>$m[1]==='enrollment'?'enrollment_followup':'attendance_followup',...$row];}
    private function assertManageSource(array $auth,string $key):void{$this->executive($auth);$source=$this->prioritySource($key);if(empty($source['ward_id']))throw new RuntimeException('Priority source has no valid operational ward.');}
    private function assertExecutiveOwner(string $owner):void{$s=$this->db->pdo()->prepare('SELECT 1 FROM users WHERE id=:id AND role IN ("super_admin","program_admin") AND is_active=1');$s->execute(['id'=>$owner]);if(!$s->fetch())throw new RuntimeException('Executive pack owner must be an active Super Admin or Program Admin.');}
    private function schedule(string $id):array{$s=$this->db->pdo()->prepare('SELECT s.*,u.name AS owner_name,c.name AS created_by_name FROM executive_dashboard_schedules s INNER JOIN users u ON u.id=s.owner_user_id INNER JOIN users c ON c.id=s.created_by WHERE s.id=:id');$s->execute(['id'=>$id]);return$s->fetch()?:throw new RuntimeException('Executive schedule not found.');}
    private function scheduleMonthPack(string $scheduleId,string $month):?array{$s=$this->db->pdo()->prepare('SELECT p.*,s.schedule_name,u.name AS generated_by_name FROM executive_dashboard_packs p LEFT JOIN executive_dashboard_schedules s ON s.id=p.schedule_id INNER JOIN users u ON u.id=p.generated_by WHERE p.schedule_id=:schedule AND p.period_month=:month LIMIT 1');$s->execute(['schedule'=>$scheduleId,'month'=>$month]);return$s->fetch()?:null;}
    private function pack(string $id):array{$s=$this->db->pdo()->prepare('SELECT p.*,s.schedule_name,u.name AS generated_by_name FROM executive_dashboard_packs p LEFT JOIN executive_dashboard_schedules s ON s.id=p.schedule_id INNER JOIN users u ON u.id=p.generated_by WHERE p.id=:id');$s->execute(['id'=>$id]);return$s->fetch()?:throw new RuntimeException('Executive dashboard pack not found.');}
    private function esc(string $value):string{return htmlspecialchars($value,ENT_QUOTES,'UTF-8');}
}
